import {
  getLatestRecordedMonth,
  getMonthlyReport,
  getSchoolYearHistory,
  type MonthlyReportData,
} from '../../../lib/mock-db'
import type { SchoolYearSettings } from '../../../lib/schoolYear'

/**
 * Reports (#19–#21). Every figure is generated by the data layer from raw records for the chosen
 * month (visit/incident/follow-up counts, the incident archive, visits per complaint), so a report
 * always matches the list screens it summarizes. `month` is "YYYY-MM".
 */
export type { MonthlyReportData }

export function fetchMonthlyReport(month: string): Promise<MonthlyReportData> {
  return getMonthlyReport(month)
}

/** What the Admin's month drop-down needs (ADR-077): the school-year starts and the newest month with records. */
export async function fetchReportMonthSetup(): Promise<{
  settings: SchoolYearSettings
  latest: string
}> {
  const [settings, latest] = await Promise.all([getSchoolYearHistory(), getLatestRecordedMonth()])
  return { settings, latest }
}
